export function touchLocalUpdate() {
  try {
    localStorage.setItem(LAST_LOCAL_UPDATE_KEY, Date.now().toString());
  } catch (e) {}
}

export function getLocalUpdateTimestamp() {
  try {
    return Number(localStorage.getItem(LAST_LOCAL_UPDATE_KEY)) || 0;
  } catch (e) {
    return 0;
  }
}

