/**
 * Synchronously get stored section media from localStorage cache with default fallback
 */
export function getStoredSectionMediaSync() {
  try {
    const cached = localStorage.getItem(SECTION_MEDIA_CACHE_KEY);
    if (cached) {
      const parsed = JSON.parse(cached);
      return {
        ...DEFAULT_SECTION_MEDIA,
        ...parsed
      };
    }
  } catch (e) {}
  return DEFAULT_SECTION_MEDIA;
}

/**
 * Save Section-Specific Media (Logo, Hero, About, Celebrations, etc.)
 * Direct Firebase Storage CDN upload + fast local persistence.
 */
export async function saveSectionMedia(sectionKey, fileOrUrl, meta = {}, onProgress = null) {
  touchLocalUpdate();
  try {
    let savedRecord = null;
    let isVideo = false;
    let fileName = meta.title || 'Resort Media';

    if (typeof fileOrUrl === 'string') {
      isVideo = fileOrUrl.includes('youtube.com') || fileOrUrl.includes('youtu.be') || fileOrUrl.includes('vimeo.com') || fileOrUrl.includes('drive.google.com') || fileOrUrl.includes('firebasestorage.googleapis.com') || fileOrUrl.endsWith('.mp4') || fileOrUrl.endsWith('.webm') || meta.mediaType === 'video';
      fileName = meta.title || fileOrUrl.split('/').pop() || 'Custom Video Link';
      savedRecord = {
        sectionKey,
        fileName,
        mediaType: isVideo ? 'video' : 'image',
        videoType: isVideo ? 'custom_url' : undefined,
        customVideoUrl: isVideo ? fileOrUrl : null,
        customUrl: fileOrUrl,
        url: fileOrUrl,
        title: meta.title || fileName,
        updatedAt: new Date().toISOString(),
        isDefault: false,
        ...meta
      };
    } else {
      isVideo = fileOrUrl.type ? fileOrUrl.type.startsWith('video/') : (fileOrUrl.name && /\.(mp4|webm|mov|mkv|m4v|ogg)$/i.test(fileOrUrl.name));
      fileName = fileOrUrl.name || 'uploaded_media';
      
      if (isVideo) {
        let cdnUrl = null;

        // Direct Cloud Storage / Stream upload (Single Clean Pass)
        try {
          cdnUrl = await uploadVideoToFirebaseStorage(fileOrUrl, 'resort_videos', onProgress);
        } catch (fbErr) {
          console.warn('[Storage] Video upload notice:', fbErr?.message || fbErr);
        }

        if (cdnUrl && typeof cdnUrl === 'string' && cdnUrl.startsWith('http')) {
          savedRecord = {
            sectionKey,
            fileName,
            mediaType: 'video',
            videoType: 'custom_url',
            customVideoUrl: cdnUrl,
            customUrl: cdnUrl,
            url: cdnUrl,
            title: meta.title || fileName,
            updatedAt: new Date().toISOString(),
            isDefault: false,
            ...meta
          };
        } else if (cdnUrl && typeof cdnUrl === 'object' && cdnUrl.videoType === 'firestore_stream') {
          const instantBlobUrl = createBlobUrl(fileOrUrl) || '';
          savedRecord = {
            sectionKey,
            fileName,
            mediaType: 'video',
            videoType: 'firestore_stream',
            ...cdnUrl,
            fileBlob: fileOrUrl,
            customVideoUrl: instantBlobUrl,
            customUrl: instantBlobUrl,
            url: instantBlobUrl,
            title: meta.title || fileName,
            updatedAt: new Date().toISOString(),
            isDefault: false,
            ...meta
          };
        } else {
          // Fallback to local asset / bundled video path
          const fallbackPath = '/assets/resort_tour_video.mp4';
          const instantBlobUrl = createBlobUrl(fileOrUrl) || fallbackPath;
          savedRecord = {
            sectionKey,
            fileName,
            mediaType: 'video',
            videoType: 'custom_url',
            fileBlob: fileOrUrl,
            customVideoUrl: instantBlobUrl,
            customUrl: instantBlobUrl,
            url: instantBlobUrl,
            title: meta.title || fileName,
            updatedAt: new Date().toISOString(),
            isDefault: false,
            ...meta
          };
        }
      } else {
        // High-res Image Data URL (compressed to crisp 1280px JPEG)
        const finalUrl = await compressImageToDataUrl(fileOrUrl, 1280, 0.82);
        savedRecord = {
          sectionKey,
          fileName,
          mediaType: 'image',
          customUrl: finalUrl,
          url: finalUrl,
          title: meta.title || fileName,
          updatedAt: new Date().toISOString(),
          isDefault: false,
          ...meta
        };
      }
    }

    // 1. Save synchronously to localStorage cache for instant zero-latency UI rendering
    try {
      const currentCache = getStoredSectionMediaSync();
      const storageRecord = {
        ...savedRecord,
        fileBlob: undefined,
        url: savedRecord.videoType === 'firestore_stream' ? undefined : savedRecord.url,
        customUrl: savedRecord.videoType === 'firestore_stream' ? undefined : savedRecord.customUrl,
        customVideoUrl: savedRecord.videoType === 'firestore_stream' ? undefined : savedRecord.customVideoUrl
      };
      const updatedCache = {
        ...currentCache,
        [sectionKey]: storageRecord
      };
      localStorage.setItem(SECTION_MEDIA_CACHE_KEY, JSON.stringify(updatedCache));
    } catch (cacheErr) {
      console.warn('[Storage] Local storage cache notice:', cacheErr);
    }

    // 2. Save locally in IndexedDB with raw blob if present
    try {
      const db = await openDB();
      const transaction = db.transaction(SECTION_MEDIA_STORE, 'readwrite');
      const store = transaction.objectStore(SECTION_MEDIA_STORE);
      const idbRecord = typeof fileOrUrl === 'object' ? { ...savedRecord, fileBlob: fileOrUrl } : savedRecord;
      store.put(idbRecord);
    } catch (idbErr) {
      console.warn('[Storage] IndexedDB put notice:', idbErr);
    }

    // 3. Broadcast and sync to Cloud & Firebase in real-time
    try {
      const allCurrent = await getAllSectionMedia();
      const cleanCurrent = {};
      Object.entries(allCurrent).forEach(([k, v]) => {
        if (v && v.sectionKey) {
          const isStream = v.videoType === 'firestore_stream';
          const u = isStream ? undefined : (
            (v.customUrl && !v.customUrl.startsWith('blob:') && !v.customUrl.startsWith('data:video'))
              ? v.customUrl
              : (v.url && !v.url.startsWith('blob:') && !v.url.startsWith('data:video'))
                ? v.url
                : v.customVideoUrl || null
          );

          cleanCurrent[k] = {
            sectionKey: v.sectionKey,
            mediaType: v.mediaType || 'image',
            videoType: v.videoType || (v.mediaType === 'video' ? 'custom_url' : undefined),
            ...(isStream ? {
              mediaKey: v.mediaKey || v.sectionKey,
              totalChunks: v.totalChunks,
              totalSize: v.totalSize,
              mimeType: v.mimeType
            } : {}),
            customVideoUrl: u,
            fileName: v.fileName || '',
            title: v.title || '',
            customUrl: u,
            url: u,
            updatedAt: v.updatedAt || new Date().toISOString(),
            isDefault: !!v.isDefault
          };
        }
      });

      const isStreamRecord = savedRecord.videoType === 'firestore_stream';
      const activeRecordUrl = isStreamRecord ? undefined : (
        (savedRecord.url && !savedRecord.url.startsWith('blob:') && !savedRecord.url.startsWith('data:video'))
          ? savedRecord.url
          : (savedRecord.customUrl && !savedRecord.customUrl.startsWith('blob:') && !savedRecord.customUrl.startsWith('data:video'))
            ? savedRecord.customUrl
            : savedRecord.customVideoUrl
      );

      const updatedCloudMap = {
        ...cleanCurrent,
        [sectionKey]: {
          sectionKey,
          mediaType: savedRecord.mediaType || (isVideo ? 'video' : 'image'),
          videoType: savedRecord.videoType || (isVideo ? 'custom_url' : undefined),
          ...(isStreamRecord ? {
            mediaKey: savedRecord.mediaKey || sectionKey,
            totalChunks: savedRecord.totalChunks,
            totalSize: savedRecord.totalSize,
            mimeType: savedRecord.mimeType
          } : {}),
          customVideoUrl: activeRecordUrl,
          fileName: savedRecord.fileName,
          title: savedRecord.title,
          customUrl: activeRecordUrl,
          url: activeRecordUrl,
          updatedAt: savedRecord.updatedAt,
          isDefault: false
        }
      };

      await saveToFirebaseCloud('sectionMedia', updatedCloudMap);
      pushCloudUpdate('sectionMedia', updatedCloudMap);
    } catch (syncErr) {
      console.warn('[Storage] Cloud sync error:', syncErr);
    }

    return savedRecord;
  } catch (error) {
    console.error(`Error saving section media (${sectionKey}):`, error);
    const fallbackUrl = typeof fileOrUrl === 'string' ? fileOrUrl : createBlobUrl(fileOrUrl);
    return {
      sectionKey,
      mediaType: (fileOrUrl.type && fileOrUrl.type.startsWith('video/')) ? 'video' : 'image',
      url: fallbackUrl,
      customUrl: fallbackUrl,
      isDefault: false,
      ...meta
    };
  }
}

/**
 * Retrieve Section-Specific Media from IndexedDB / Cloud Cache
 */
export async function getSectionMedia(sectionKey) {
  try {
    const db = await openDB();
    const transaction = db.transaction(SECTION_MEDIA_STORE, 'readonly');
    const store = transaction.objectStore(SECTION_MEDIA_STORE);

    return new Promise((resolve) => {
      const request = store.get(sectionKey);
      request.onsuccess = (event) => {
        const result = event.target.result;
        if (result) {
          const url = result.customUrl || result.url || (result.fileBlob ? createBlobUrl(result.fileBlob) : null);
          resolve({ ...result, url });
        } else {
          const syncCache = getStoredSectionMediaSync();
          resolve(syncCache[sectionKey] || DEFAULT_SECTION_MEDIA[sectionKey] || null);
        }
      };
      request.onerror = () => {
        const syncCache = getStoredSectionMediaSync();
        resolve(syncCache[sectionKey] || DEFAULT_SECTION_MEDIA[sectionKey] || null);
      };
    });
  } catch (e) {
    console.warn(`Error getting section media (${sectionKey}):`, e);
    const syncCache = getStoredSectionMediaSync();
    return syncCache[sectionKey] || DEFAULT_SECTION_MEDIA[sectionKey] || null;
  }
}

/**
 * Get all Section Media items as a key-value dictionary
 */
export async function getAllSectionMedia() {
  const syncCache = getStoredSectionMediaSync();
  try {
    const db = await openDB();
    const transaction = db.transaction(SECTION_MEDIA_STORE, 'readonly');
    const store = transaction.objectStore(SECTION_MEDIA_STORE);

    return new Promise((resolve) => {
      const request = store.getAll();
      request.onsuccess = (event) => {
        const results = event.target.result || [];
        const mediaMap = { ...DEFAULT_SECTION_MEDIA, ...syncCache };
        results.forEach(item => {
          if (item && item.sectionKey) {
            const url = item.customUrl || item.url || (item.fileBlob ? createBlobUrl(item.fileBlob) : null);
            mediaMap[item.sectionKey] = {
              ...item,
              url: url || mediaMap[item.sectionKey]?.url
            };
          }
        });
        resolve(mediaMap);
      };
      request.onerror = () => resolve(syncCache);
    });
  } catch (e) {
    console.warn('Error fetching all section media:', e);
    return syncCache;
  }
}

/**
 * Delete a Section-Specific Media record (Resets section to default asset)
 */
export async function deleteSectionMedia(sectionKey) {
  touchLocalUpdate();
  try {
    // 1. Remove from localStorage cache
    try {
      const currentCache = getStoredSectionMediaSync();
      delete currentCache[sectionKey];
      localStorage.setItem(SECTION_MEDIA_CACHE_KEY, JSON.stringify(currentCache));
    } catch (e) {}

    // 2. Remove from IndexedDB
    const db = await openDB();
    const transaction = db.transaction(SECTION_MEDIA_STORE, 'readwrite');
    const store = transaction.objectStore(SECTION_MEDIA_STORE);

    await new Promise((resolve) => {
      const request = store.delete(sectionKey);
      request.onsuccess = () => resolve(true);
      request.onerror = () => resolve(false);
    });

    // 3. Cloud Sync deletion
    try {
      const allCurrent = await getAllSectionMedia();
      const updated = { ...allCurrent };
      delete updated[sectionKey];
      await saveToFirebaseCloud('sectionMedia', updated);
      pushCloudUpdate('sectionMedia', updated);
    } catch(e) {}

    return true;
  } catch (error) {
    console.error(`Failed to delete section media (${sectionKey}):`, error);
    return false;
  }
}

/**
 * Synchronously get stored gallery items from localStorage cache
 */
export function getStoredGallerySync() {
  try {
    const cached = localStorage.getItem(GALLERY_CACHE_KEY);
    if (cached) {
      const parsed = JSON.parse(cached);
      if (Array.isArray(parsed) && parsed.length > 0) {
        return parsed;
      }
    }
  } catch (e) {}
  return DEFAULT_GALLERY_ITEMS;
}

/**
 * Save custom media item to Gallery with Cloud Sync
 */
export async function saveMediaItem(mediaMeta, file, onProgress = null) {
  touchLocalUpdate();
  try {
    const isVideo = file.type ? file.type.startsWith('video/') : (file.name && /\.(mp4|webm|mov|mkv|m4v|ogg)$/i.test(file.name));
    let permanentUrl = null;

    // Upload to Storage CDN or compress to high-res Web Data URL
    try {
      permanentUrl = await uploadMediaToFirebaseStorage(file, 'gallery', onProgress);
    } catch (e) {
      permanentUrl = null;
    }

    if (!permanentUrl || permanentUrl.startsWith('blob:')) {
      permanentUrl = await readFileAsDataUrl(file).catch(() => createBlobUrl(file));
    }

    const record = {
      id: mediaMeta.id || 'media-' + Date.now() + '-' + Math.random().toString(36).substr(2, 4),
      title: mediaMeta.title || file.name || 'Gallery Item',
      category: mediaMeta.category || 'General',
      type: isVideo ? 'video' : 'image',
      videoType: isVideo ? (permanentUrl.includes('cloudinary') ? 'cloudinary' : 'custom') : undefined,
      fileName: file.name || 'media_file',
      customUrl: permanentUrl,
      url: permanentUrl,
      uploadedAt: new Date().toISOString().split('T')[0],
      isDefault: false
    };

    // 1. Save to IndexedDB
    try {
      const db = await openDB();
      const transaction = db.transaction(GALLERY_STORE, 'readwrite');
      const store = transaction.objectStore(GALLERY_STORE);
      await new Promise((resolve) => {
        const idbRecord = { ...record, fileBlob: file };
        const request = store.put(idbRecord);
        request.onsuccess = () => resolve(true);
        request.onerror = () => resolve(false);
      });
    } catch (idbErr) {
      console.warn('[Storage] IndexedDB gallery put notice:', idbErr);
    }

    // 2. Real-time Cloud Sync & localStorage cache
    try {
      const currentCache = getStoredGallerySync();
      const cleanGallery = [...currentCache.filter(item => item.id !== record.id), record].map(item => ({
        id: item.id,
        title: item.title,
        category: item.category,
        type: item.type,
        url: item.id === record.id ? record.url : (item.customUrl || (item.url && !item.url.startsWith('blob:') ? item.url : null)),
        uploadedAt: item.uploadedAt,
        isDefault: !!item.isDefault
      }));

      try {
        localStorage.setItem(GALLERY_CACHE_KEY, JSON.stringify(cleanGallery));
      } catch (cacheErr) {}

      await saveToFirebaseCloud('gallery', cleanGallery);
      pushCloudUpdate('gallery', cleanGallery);
    } catch (e) {}

    return record;
  } catch (error) {
    console.error('Error saving media to Gallery:', error);
    return {
      id: 'media-' + Date.now(),
      title: mediaMeta.title || file.name,
      category: mediaMeta.category || 'General',
      type: file.type?.startsWith('video/') ? 'video' : 'image',
      url: createBlobUrl(file),
      isDefault: false
    };
  }
}

/**
 * Fetch all gallery media items
 */
export async function getAllGalleryItems() {
  const syncCache = getStoredGallerySync();
  try {
    const db = await openDB();
    const transaction = db.transaction(GALLERY_STORE, 'readonly');
    const store = transaction.objectStore(GALLERY_STORE);

    return new Promise((resolve) => {
      const request = store.getAll();
      request.onsuccess = (event) => {
        const idbItems = event.target.result || [];
        const mergedMap = new Map();
        
        // 1. Add Default items
        DEFAULT_GALLERY_ITEMS.forEach(it => mergedMap.set(it.id, it));
        // 2. Add Cached items
        syncCache.forEach(it => {
          if (it && it.id) mergedMap.set(it.id, it);
        });
        // 3. Add IDB items
        idbItems.forEach(it => {
          if (it && it.id) {
            const url = it.customUrl || it.url || (it.fileBlob ? createBlobUrl(it.fileBlob) : null);
            mergedMap.set(it.id, { ...it, url: url || it.url });
          }
        });
        resolve(Array.from(mergedMap.values()));
      };
      request.onerror = () => {
        resolve(syncCache);
      };
    });
  } catch (e) {
    console.warn('Falling back to sync cache gallery items:', e);
    return syncCache;
  }
}

/**
 * Delete a gallery media item by ID
 */
export async function deleteMediaItem(id) {
  touchLocalUpdate();
  try {
    const db = await openDB();
    const transaction = db.transaction(GALLERY_STORE, 'readwrite');
    const store = transaction.objectStore(GALLERY_STORE);
    
    await new Promise((resolve) => {
      const request = store.delete(id);
      request.onsuccess = () => resolve(true);
      request.onerror = () => resolve(false);
    });

    try {
      const currentCache = getStoredGallerySync();
      const cleanGallery = currentCache.filter(item => item.id !== id).map(item => ({
        id: item.id,
        title: item.title,
        category: item.category,
        type: item.type,
        url: item.customUrl || (item.url && !item.url.startsWith('blob:') ? item.url : null),
        uploadedAt: item.uploadedAt,
        isDefault: !!item.isDefault
      }));

      try {
        localStorage.setItem(GALLERY_CACHE_KEY, JSON.stringify(cleanGallery));
      } catch (e) {}

      await saveToFirebaseCloud('gallery', cleanGallery);
      pushCloudUpdate('gallery', cleanGallery);
    } catch(e) {}

    return true;
  } catch (error) {
    console.error('Failed to delete media:', error);
    return false;
  }
}

