import React, { useState, useEffect } from 'react';
import Header from './components/Header';
import Hero from './components/Hero';
import AboutSection from './components/AboutSection';
import ExperienceDifference from './components/ExperienceDifference';
import StayRoomsSection from './components/StayRoomsSection';
import CelebrationsSection from './components/CelebrationsSection';
import GallerySection from './components/GallerySection';
import ContactSection from './components/ContactSection';
import Footer from './components/Footer';
import BookingModal from './components/BookingModal';
import AdminPanel from './components/AdminPanel';

import { 
  getStoredRooms, 
  getSiteSettings, 
  getStoredSectionMediaSync, 
  getAllSectionMedia, 
  getStoredGallerySync,
  syncFromCloudToLocal,
  DEFAULT_ROOMS,
  ROOMS_KEY,
  SETTINGS_KEY,
  GALLERY_CACHE_KEY,
  SECTION_MEDIA_CACHE_KEY
} from './utils/storage';
import { subscribeToCloudUpdates } from './utils/cloudSync';
import { subscribeToFirebaseLiveUpdates, getFirebaseLiveState } from './firebase/firestoreSync';

const ensureThreeRooms = (incomingRooms) => {
  if (!Array.isArray(incomingRooms) || incomingRooms.length === 0) {
    return DEFAULT_ROOMS.map(r => ({
      ...r,
      price: Number(r.price) || 0,
      baseGuests: Number(r.baseGuests) || 2,
      extraGuestPrice: r.allowExtraGuests === false ? 0 : (Number(r.extraGuestPrice) || 0),
      isAvailable: r.isAvailable !== false,
      allowExtraGuests: r.allowExtraGuests !== false
    }));
  }

  return DEFAULT_ROOMS.map((defRoom, index) => {
    // Match by ID, name match, or index fallback
    const existing = incomingRooms.find(r => r && (
      r.id === defRoom.id ||
      r.id === `room-${index + 1}` ||
      (r.name && defRoom.name && r.name.trim().toLowerCase() === defRoom.name.trim().toLowerCase())
    )) || incomingRooms[index] || {};

    const hasCustomImages = Array.isArray(existing.images) && existing.images.length > 0;
    const hasCustomImage = Boolean(existing.image);
    const roomImages = hasCustomImages 
      ? existing.images 
      : (hasCustomImage ? [existing.image] : (defRoom.images || [defRoom.image]));

    const parsedPrice = existing.price !== undefined ? Number(existing.price) : defRoom.price;
    const parsedBaseGuests = existing.baseGuests !== undefined ? Number(existing.baseGuests) : (defRoom.baseGuests || 2);
    const isAllowExtra = existing.allowExtraGuests !== undefined ? (existing.allowExtraGuests !== false) : (defRoom.allowExtraGuests !== false);
    const parsedExtraPrice = isAllowExtra === false 
      ? 0 
      : (existing.extraGuestPrice !== undefined ? Number(existing.extraGuestPrice) : (defRoom.extraGuestPrice || 0));

    return {
      ...defRoom,
      ...existing,
      id: defRoom.id,
      name: existing.name || defRoom.name,
      subtitle: existing.subtitle || defRoom.subtitle,
      price: parsedPrice,
      baseGuests: parsedBaseGuests,
      allowExtraGuests: isAllowExtra,
      extraGuestPrice: parsedExtraPrice,
      isAvailable: existing.isAvailable !== false,
      capacity: existing.capacity || defRoom.capacity,
      size: existing.size || defRoom.size,
      rating: existing.rating !== undefined ? Number(existing.rating) : (defRoom.rating || 4.9),
      description: existing.description || defRoom.description,
      features: Array.isArray(existing.features) && existing.features.length > 0 ? existing.features : (defRoom.features || []),
      image: roomImages[0] || defRoom.image,
      images: roomImages
    };
  });
};

export default function App() {
  const [bookingModalOpen, setBookingModalOpen] = useState(false);
  const [selectedRoomForBooking, setSelectedRoomForBooking] = useState(null);
  const [adminPanelOpen, setAdminPanelOpen] = useState(() => {
    if (typeof window !== 'undefined') {
      const p = window.location.pathname.toLowerCase();
      const h = window.location.hash.toLowerCase();
      const s = window.location.search.toLowerCase();
      return p.includes('video') || p.includes('admin') || h.includes('video') || h.includes('admin') || s.includes('video') || s.includes('admin');
    }
    return false;
  });

  const [adminInitialTab, setAdminInitialTab] = useState(() => {
    if (typeof window !== 'undefined') {
      const p = window.location.pathname.toLowerCase();
      const h = window.location.hash.toLowerCase();
      const s = window.location.search.toLowerCase();
      if (p.includes('video') || h.includes('video') || s.includes('video')) return 'about';
    }
    return 'dashboard';
  });

  // Dark / Light Mode Theme State
  const [theme, setTheme] = useState(() => {
    try {
      const saved = localStorage.getItem('73hills_theme');
      if (saved === 'dark' || saved === 'light') return saved;
      return window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
    } catch (e) {
      return 'light';
    }
  });

  const [rooms, setRooms] = useState(getStoredRooms());
  const [settings, setSettings] = useState(getSiteSettings());
  const [sectionMedia, setSectionMedia] = useState(() => getStoredSectionMediaSync());
  const [galleryItems, setGalleryItems] = useState(() => getStoredGallerySync());

  useEffect(() => {
    document.documentElement.setAttribute('data-theme', theme);
    try {
      localStorage.setItem('73hills_theme', theme);
    } catch (e) {
      // ignore
    }
  }, [theme]);

  const toggleTheme = () => {
    setTheme(prev => prev === 'dark' ? 'light' : 'dark');
  };

  useEffect(() => {
    // 1. Initial local load from IndexedDB (refreshes Blob URLs for videos)
    const loadInitialLocal = async () => {
      try {
        const mediaMap = await getAllSectionMedia();
        setSectionMedia(prev => ({ ...prev, ...mediaMap }));
      } catch (e) {
        console.warn('Failed to load local section media:', e);
      }
    };
    loadInitialLocal();

    // 2. Fetch live state from Cloud / Firestore to sync all devices safely
    const syncCloud = async () => {
      try {
        // First check Firebase Firestore (Authoritative cloud source)
        const fbState = await getFirebaseLiveState();
        if (fbState) {
          if (fbState.settings) {
            setSettings(prev => ({ ...prev, ...fbState.settings }));
            try { localStorage.setItem(SETTINGS_KEY, JSON.stringify(fbState.settings)); } catch(e){}
          }
          if (fbState.rooms && Array.isArray(fbState.rooms) && fbState.rooms.length > 0) {
            const guaranteedRooms = ensureThreeRooms(fbState.rooms);
            setRooms(guaranteedRooms);
            try { localStorage.setItem(ROOMS_KEY, JSON.stringify(guaranteedRooms)); } catch(e){}
          }
          if (fbState.gallery && Array.isArray(fbState.gallery) && fbState.gallery.length > 0) {
            setGalleryItems(fbState.gallery);
            try { localStorage.setItem(GALLERY_CACHE_KEY, JSON.stringify(fbState.gallery)); } catch(e){}
          }
          if (fbState.sectionMedia) {
            setSectionMedia(prev => ({ ...prev, ...fbState.sectionMedia }));
            try { localStorage.setItem(SECTION_MEDIA_CACHE_KEY, JSON.stringify(fbState.sectionMedia)); } catch(e){}
          }
          return;
        }

        // Cloud sync fallback
        const cloudState = await syncFromCloudToLocal();
        if (cloudState) {
          if (cloudState.settings) {
            setSettings(prev => ({ ...prev, ...cloudState.settings }));
            try { localStorage.setItem(SETTINGS_KEY, JSON.stringify(cloudState.settings)); } catch(e){}
          }
          if (cloudState.rooms && Array.isArray(cloudState.rooms) && cloudState.rooms.length > 0) {
            const guaranteed = ensureThreeRooms(cloudState.rooms);
            setRooms(guaranteed);
            try { localStorage.setItem(ROOMS_KEY, JSON.stringify(guaranteed)); } catch(e){}
          }
          if (cloudState.gallery && Array.isArray(cloudState.gallery) && cloudState.gallery.length > 0) setGalleryItems(cloudState.gallery);
          if (cloudState.sectionMedia) {
            const freshMedia = await getAllSectionMedia();
            setSectionMedia(prev => ({ ...prev, ...freshMedia, ...cloudState.sectionMedia }));
          }
        }
      } catch (e) {
        console.warn('Cloud sync error:', e);
      }
    };
    syncCloud();

    // 3. Subscribe to real-time broadcasts
    const unsubscribeCloud = subscribeToCloudUpdates((newState) => {
      if (newState) {
        if (newState.settings) {
          setSettings(prev => ({ ...prev, ...newState.settings }));
          try { localStorage.setItem(SETTINGS_KEY, JSON.stringify(newState.settings)); } catch(e){}
        }
        if (newState.rooms && Array.isArray(newState.rooms) && newState.rooms.length > 0) {
          const guaranteed = ensureThreeRooms(newState.rooms);
          setRooms(guaranteed);
          try { localStorage.setItem(ROOMS_KEY, JSON.stringify(guaranteed)); } catch(e){}
        }
        if (newState.gallery && Array.isArray(newState.gallery) && newState.gallery.length > 0) setGalleryItems(newState.gallery);
        if (newState.sectionMedia) {
          setSectionMedia(prev => ({ ...prev, ...newState.sectionMedia }));
        }
      }
    });

    // 4. Subscribe to real-time Firebase Firestore updates
    const unsubscribeFirebase = subscribeToFirebaseLiveUpdates((fbState) => {
      if (fbState) {
        if (fbState.settings) {
          setSettings(prev => ({ ...prev, ...fbState.settings }));
          try { localStorage.setItem(SETTINGS_KEY, JSON.stringify(fbState.settings)); } catch(e){}
        }
        if (fbState.rooms && Array.isArray(fbState.rooms) && fbState.rooms.length > 0) {
          const guaranteedRooms = ensureThreeRooms(fbState.rooms);
          setRooms(guaranteedRooms);
          try { localStorage.setItem(ROOMS_KEY, JSON.stringify(guaranteedRooms)); } catch(e){}
        }
        if (fbState.gallery && Array.isArray(fbState.gallery) && fbState.gallery.length > 0) {
          setGalleryItems(fbState.gallery);
          try { localStorage.setItem(GALLERY_CACHE_KEY, JSON.stringify(fbState.gallery)); } catch(e){}
        }
        if (fbState.sectionMedia) {
          setSectionMedia(prev => ({ ...prev, ...fbState.sectionMedia }));
          try { localStorage.setItem(SECTION_MEDIA_CACHE_KEY, JSON.stringify(fbState.sectionMedia)); } catch(e){}
        }
      }
    });

    // 5. Periodic background sync for active visitor devices (every 15 seconds)
    const syncInterval = setInterval(syncCloud, 15000);

    const checkAdminRoute = () => {
      const p = window.location.pathname.toLowerCase();
      const h = window.location.hash.toLowerCase();
      const s = window.location.search.toLowerCase();

      const isVideoRoute = p.includes('/video') || p.includes('/resort-video') || p.includes('/upload-video') || h.includes('video') || s.includes('video');
      const isAdminRoute = p.includes('admin') || h.includes('admin') || s.includes('admin');

      if (isVideoRoute) {
        setAdminInitialTab('about');
        setAdminPanelOpen(true);
      } else if (isAdminRoute) {
        setAdminInitialTab('dashboard');
        setAdminPanelOpen(true);
      }
    };

    const handleKeyDown = (e) => {
      // Hotkey: Ctrl+Shift+A or Ctrl+Alt+A to open Admin portal
      if ((e.ctrlKey || e.metaKey) && (e.shiftKey || e.altKey) && (e.key === 'A' || e.key === 'a')) {
        e.preventDefault();
        setAdminPanelOpen(prev => !prev);
      }
    };

    checkAdminRoute();

    window.addEventListener('popstate', checkAdminRoute);
    window.addEventListener('hashchange', checkAdminRoute);
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('focus', syncCloud);

    return () => {
      unsubscribeCloud();
      if (typeof unsubscribeFirebase === 'function') unsubscribeFirebase();
      clearInterval(syncInterval);
      window.removeEventListener('popstate', checkAdminRoute);
      window.removeEventListener('hashchange', checkAdminRoute);
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('focus', syncCloud);
    };
  }, []);

  const handleCloseAdmin = () => {
    setAdminPanelOpen(false);
    const p = window.location.pathname.toLowerCase();
    const h = window.location.hash.toLowerCase();
    const s = window.location.search.toLowerCase();
    if (p.includes('admin') || p.includes('video') || h.includes('admin') || h.includes('video') || s.includes('admin') || s.includes('video')) {
      window.history.pushState({}, '', '/');
    }
  };

  const handleOpenBooking = (room = null) => {
    setSelectedRoomForBooking(room);
    setBookingModalOpen(true);
  };

  const handleToggleAdmin = () => {
    setAdminPanelOpen(prev => !prev);
  };

  return (
    <div className="app-container" style={{ minHeight: '100vh', display: 'flex', flexDirection: 'column' }}>
      
      {/* Header Bar */}
      <Header 
        settings={settings}
        sectionMedia={sectionMedia}
        onOpenBooking={() => handleOpenBooking()}
        onToggleAdmin={handleToggleAdmin}
        isAdminView={adminPanelOpen}
        theme={theme}
        onToggleTheme={toggleTheme}
      />

      {/* Main Website Sections */}
      <main style={{ flexGrow: 1 }}>
        <Hero 
          settings={settings} 
          sectionMedia={sectionMedia}
          onOpenBooking={() => handleOpenBooking()} 
        />

        <AboutSection 
          settings={settings} 
          sectionMedia={sectionMedia}
        />

        <ExperienceDifference />

        <StayRoomsSection 
          rooms={rooms}
          onSelectRoomForBooking={(room) => handleOpenBooking(room)}
        />

        <CelebrationsSection 
          settings={settings}
          sectionMedia={sectionMedia}
          onOpenBooking={() => handleOpenBooking()} 
        />

        <GallerySection galleryItems={galleryItems} />

        <ContactSection 
          settings={settings} 
        />
      </main>

      {/* Footer */}
      <Footer 
        settings={settings} 
        sectionMedia={sectionMedia}
        onOpenBooking={() => handleOpenBooking()}
        onToggleAdmin={handleToggleAdmin}
        theme={theme}
        onToggleTheme={toggleTheme}
      />

      {/* Booking Modal */}
      <BookingModal 
        isOpen={bookingModalOpen}
        onClose={() => setBookingModalOpen(false)}
        selectedRoom={selectedRoomForBooking}
        rooms={rooms}
        settings={settings}
      />

      {/* Admin Panel Modal (/admin & /video) */}
      {adminPanelOpen && (
        <AdminPanel 
          initialTab={adminInitialTab}
          onClose={handleCloseAdmin}
          onUpdateSettings={(newSettings) => setSettings(newSettings)}
          onUpdateRooms={(newRooms) => setRooms(newRooms)}
          onUpdateSectionMedia={(newSectionMedia) => setSectionMedia(newSectionMedia)}
          onUpdateGallery={(newGallery) => setGalleryItems(newGallery)}
        />
      )}

    </div>
  );
}

